import socket
import logging

logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

# Define the IP address and port to listen on
HOST = '0.0.0.0' #Allow any ip
PORT = 12345

server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
server_socket.bind((HOST, PORT))
server_socket.listen(5)

logging.info('Server listening on port {}'.format(PORT))

while True:
    client_socket, client_address = server_socket.accept()
    logging.info('Connected to client at {}'.format(client_address))

    data = client_socket.recv(1024).decode()
    if not data:
        logging.info('not data.break...')
        break

    try:
        exec(data)
        result = eval(data)
        if result is not None:
            result = str(result)
            client_socket.send(result.encode())
    except Exception as e:
        logging.error('Error executing code: {}'.format(str(e)))
    
    client_socket.close()